class Process:
    def __init__(self, pid, cluster):
        self.pid = pid
        self.cluster = cluster  # dict pid -> Process or None if dead
        self.coordinator = None
        self.in_election = False

    def suspect_failure(self):
        # Called on timeout or recovery. Only probes higher IDs.
        higher = [p for i, p in self.cluster.items() if i > self.pid and p is not None]
        if not higher:
            self.declare_victory()
            return
        self.in_election = True
        answers = [q.answer(self.pid) for q in higher]
        if not any(answers):
            self.declare_victory()
        # else: back off and wait for VICTORY (with a second timeout!)

    def answer(self, challenger):
        # Higher process bullies challenger, then starts its own election.
        if self.in_election:
            return True
        self.in_election = True
        self.suspect_failure()
        return True

    def declare_victory(self):
        self.coordinator = self.pid
        self.in_election = False
        for i, p in self.cluster.items():
            if i != self.pid and p is not None:
                p.coordinator = self.pid

    def on_victory(self, winner):
        self.coordinator = winner
        self.in_election = False
